def pack_numbers(numbers):
    """Packs a list of numbers into bins with a maxmimum sum of 100"""
    bins = [[]]

    for n in numbers:
        # if current bin would be too full after adding n, create new bin first
        if sum(bins[-1]) + n > 100:
            bins.append([])

        # add n to current bin
        bins[-1].append(n)

    return bins

